package com.ruoyi.hexu;
import java.util.*;
import java.sql.Timestamp;
import java.time.*;
import java.time.temporal.ChronoUnit;
import java.math.BigDecimal;
import java.math.RoundingMode;
import static com.ruoyi.hexu.HexuStore.*;
import static com.ruoyi.hexu.BusinessException.require;

/** Durable reports aggregate a database snapshot in resumable chunks; readers never see partial totals. */
public final class HexuReports {
 private static final ZoneId ZONE=ZoneId.of("Asia/Shanghai");private final HexuStore db;
 public HexuReports(HexuStore db){this.db=db;}
 private void scope(Actor a,long shop){if(shop==0)db.platform(a);else db.manage(a,shop,"FINANCE","OPERATOR");}
 private Map<String,Object> checked(Actor a,String id){Map<String,Object>j=db.one("select * from hx_report_job where id=?",id);scope(a,number(j,"shop_id"));require(a.platform||number(j,"created_by")==a.id&&bool(j,"staff_actor")==a.staff,"无权读取其他人员的报表任务");return j;}
 private Timestamp time(String day){return Timestamp.from(LocalDate.parse(day).atStartOfDay(ZONE).toInstant());}
 public Map<String,Object> create(Actor a,long shop,Map<String,Object>b){scope(a,shop);LocalDate from,to;try{from=LocalDate.parse(str(b,"from"));to=LocalDate.parse(str(b,"to"));}catch(Exception e){throw new BusinessException("请填写有效报表起止日期");}require(!to.isAfter(LocalDate.now(ZONE))&&!to.isBefore(from)&&ChronoUnit.DAYS.between(from,to)<3660,"报表时间范围无效、超过10年或结束日期在未来");require(number(b,"rank")>=0&&number(b,"rank")<=3&&number(b,"agentId")>=0&&number(b,"customerId")>=0,"报表职级或人员编号无效");require(str(b,"county").length()<=100&&str(b,"skuId").length()<=64,"报表筛选条件过长");require(db.jdbc().queryForObject("select count(*) from hx_report_job where created_by=? and staff_actor=? and status in ('QUEUED','RUNNING')",Long.class,a.id,a.staff)<3,"已有3个报表任务运行，请等待完成");String id=id("REPORT");Map<String,Object>filters=map("from",from.toString(),"to",to.toString(),"county",str(b,"county"),"skuId",str(b,"skuId"),"rank",number(b,"rank"),"agentId",number(b,"agentId"),"customerId",number(b,"customerId"),"includeTeam",!b.containsKey("includeTeam")||bool(b,"includeTeam"));db.jdbc().update("insert into hx_report_job(id,shop_id,created_by,staff_actor,platform_actor,filters_json,status) values(?,?,?,?,?,?,'QUEUED')",id,shop,a.id,a.staff,a.platform,db.json(filters));db.audit(a,shop,"REPORT_REQUEST",id,null,filters);return view(a,id,"SHOP",1,50);}
 private List<Object> where(Map<String,Object>j,StringBuilder sql,String orderAlias,String shopAlias){Map<String,Object>f=db.parse(j.get("filters_json"));List<Object>args=new ArrayList<>();sql.append(" ").append(orderAlias).append(".created_at>=? and ").append(orderAlias).append(".created_at<?");args.add(time(str(f,"from")));args.add(time(LocalDate.parse(str(f,"to")).plusDays(1).toString()));if(number(j,"shop_id")!=0){sql.append(" and ").append(orderAlias).append(".shop_id=?");args.add(number(j,"shop_id"));}if(!str(f,"county").isEmpty()){sql.append(" and ").append(shopAlias).append(".county=?");args.add(str(f,"county"));}if(number(f,"customerId")>0){sql.append(" and ").append(orderAlias).append(".buyer_id=?");args.add(number(f,"customerId"));}return args;}
 public void process(String id){Map<String,Object>j=db.one("select * from hx_report_job where id=? for update",id);if(!Arrays.asList("QUEUED","RUNNING").contains(str(j,"status")))return;Actor a=new Actor(number(j,"created_by"),bool(j,"platform_actor"),bool(j,"staff_actor"));scope(a,number(j,"shop_id"));Map<String,Object>f=db.parse(j.get("filters_json"));if("QUEUED".equals(str(j,"status"))){StringBuilder condition=new StringBuilder();List<Object>args=where(j,condition,"o","s");if(!str(f,"skuId").isEmpty()){condition.append(" and l.sku_id=?");args.add(str(f,"skuId"));}args.add(0,id);
   db.jdbc().update("insert into hx_report_line(job_id,line_id,order_id,shop_id,shop_name,county,buyer_id,buyer_name,sku_id,sku_name,category,qty,refunded_qty,paid,refunded_paid,snapshot_json,order_status,order_type,created_at,earnings) select ?,l.id,o.id,o.shop_id,s.name,s.county,o.buyer_id,m.name,l.sku_id,l.name,coalesce(d.category,''),l.qty,l.refunded_qty,l.paid,l.refunded_paid,l.snapshot_json,o.status,o.order_type,o.created_at,coalesce((select sum(e.amount-e.reversed) from hx_earning e where e.line_id=l.id),0) from hx_order_line l join hx_order o on o.id=l.order_id join hx_shop s on s.id=o.shop_id join hx_member m on m.id=o.buyer_id left join hx_sku_detail d on d.shop_id=o.shop_id and d.sku_id=l.sku_id where o.status in ('PAID','SHIPPED','COMPLETED','REFUNDED') and"+condition,args.toArray());
   stockSnapshot(j);long total=db.jdbc().queryForObject("select count(*) from hx_report_line where job_id=?",Long.class,id);db.jdbc().update("update hx_report_job set status='RUNNING',total_rows=?,snapshot_at=CURRENT_TIMESTAMP where id=?",total,id);return;
  }
  List<Map<String,Object>>rows=db.jdbc().queryForList("select * from hx_report_line where job_id=? and line_id>? order by line_id limit 1000",id,number(j,"cursor_id"));Map<Long,String>names=new HashMap<>();for(Map<String,Object>r:rows){Map<String,Object>snap=db.parse(r.get("snapshot_json"));List<Map<String,Object>>chain=snap.get("chain") instanceof List?(List<Map<String,Object>>)snap.get("chain"):Collections.emptyList();long agent=chain.isEmpty()?number(snap,"buyerAgentId"):number(chain.get(0),"agentId"),rank=chain.isEmpty()?number(snap,"rank"):number(chain.get(0),"rank");boolean matches=(number(f,"rank")==0||number(f,"rank")==rank);if(number(f,"agentId")>0){boolean member=agent==number(f,"agentId");if(bool(f,"includeTeam"))for(Map<String,Object>n:chain)if(number(n,"agentId")==number(f,"agentId"))member=true;matches&=member;}long cost=0;if(!chain.isEmpty()&&snap.get("prices") instanceof List){int ownerRank=(int)number(chain.get(chain.size()-1),"rank");List<?>prices=(List<?>)snap.get("prices");if(ownerRank>0&&ownerRank<prices.size())cost=Math.multiplyExact(Long.parseLong(prices.get(ownerRank).toString()),number(r,"qty")-number(r,"refunded_qty"));}String name=agent==0?"未记录代理":names.computeIfAbsent(agent,key->{Map<String,Object>n=db.optional("select m.name from hx_agent a join hx_member m on m.id=a.member_id where a.id=?",key);return n==null?"代理 "+key:str(n,"name");});db.jdbc().update("update hx_report_line set agent_id=?,agent_name=?,rank_no=?,net_cost=?,matched=?,business_day=?,cost_known=?,processed=true where job_id=? and line_id=?",agent,name,rank,cost,matches,((Timestamp)r.get("created_at")).toInstant().atZone(ZONE).toLocalDate().toString(),!chain.isEmpty()&&snap.get("prices") instanceof List,id,r.get("line_id"));}
  long processed=number(j,"processed_rows")+rows.size();boolean done=processed>=number(j,"total_rows");db.jdbc().update("update hx_report_job set cursor_id=?,processed_rows=?,status=?,completed_at=? where id=?",rows.isEmpty()?number(j,"cursor_id"):number(rows.get(rows.size()-1),"line_id"),processed,done?"COMPLETED":"RUNNING",done?new Timestamp(System.currentTimeMillis()):null,id);
 }
 private void stockSnapshot(Map<String,Object>j){Map<String,Object>f=db.parse(j.get("filters_json"));long shop=number(j,"shop_id");StringBuilder filter=new StringBuilder(" where 1=1");List<Object>args=new ArrayList<>();if(shop!=0){filter.append(" and k.shop_id=?");args.add(shop);}if(!str(f,"county").isEmpty()){filter.append(" and s.county=?");args.add(str(f,"county"));}if(!str(f,"skuId").isEmpty()){filter.append(" and k.id=?");args.add(str(f,"skuId"));}LocalDate from=LocalDate.parse(str(f,"from")),to=LocalDate.parse(str(f,"to"));long days=ChronoUnit.DAYS.between(from,to)+1;Timestamp after=time(to.plusDays(1).toString()),start=time(from.toString());
  for(Map<String,Object>k:db.jdbc().queryForList("select k.* from hx_sku k join hx_shop s on s.id=k.shop_id"+filter,args.toArray())){long scope=number(k,"shop_id"),endStock=number(k,"available")+number(k,"locked"),weighted=0;for(Map<String,Object>log:db.jdbc().queryForList("select available_delta,locked_delta,created_at from hx_inventory_log where shop_id=? and sku_id=? and created_at>=?",scope,k.get("id"),start)){long delta=number(log,"available_delta")+number(log,"locked_delta");Timestamp at=(Timestamp)log.get("created_at");if(!at.before(after))endStock-=delta;else{long day=ChronoUnit.DAYS.between(from,at.toInstant().atZone(ZONE).toLocalDate());weighted=Math.addExact(weighted,Math.multiplyExact(delta,day));}}BigDecimal avg=BigDecimal.valueOf(endStock).subtract(BigDecimal.valueOf(weighted).divide(BigDecimal.valueOf(days),4,RoundingMode.HALF_UP));long transit=db.jdbc().queryForObject("select coalesce(sum(l.qty-l.refunded_qty),0) from hx_order_line l join hx_order o on o.id=l.order_id where o.destination_shop_id=? and o.order_type='WHOLESALE' and o.status='SHIPPED' and l.sku_id=?",Long.class,scope,k.get("id"));db.jdbc().update("insert into hx_report_stock(job_id,shop_id,sku_id,sku_name,available,locked,defective,warning_qty,in_transit,average_stock) values(?,?,?,?,?,?,?,?,?,?)",j.get("id"),scope,k.get("id"),k.get("name"),k.get("available"),k.get("locked"),k.get("defective"),k.get("warning_qty"),transit,avg.max(BigDecimal.ZERO));}
 }
 public List<Map<String,Object>> list(Actor a,long shop){scope(a,shop);List<Map<String,Object>>rows=db.jdbc().queryForList("select * from hx_report_job where shop_id=? and created_by=? and staff_actor=? order by created_at desc,id desc limit 50",shop,a.id,a.staff);for(Map<String,Object>r:rows){r.put("filters",db.parse(r.remove("filters_json")));r.put("progress",number(r,"total_rows")==0?("COMPLETED".equals(str(r,"status"))?100:0):number(r,"processed_rows")*100/number(r,"total_rows"));}return rows;}
 public List<Map<String,Object>> queue(){return db.jdbc().queryForList("select id from hx_report_job where status in ('QUEUED','RUNNING') order by created_at limit 5");}
 public void fail(String id,String error){db.jdbc().update("update hx_report_job set status='FAILED',error_message=? where id=?",error==null?"报表任务失败":error.substring(0,Math.min(error.length(),1000)),id);}
 private String group(String dimension){switch(dimension){case "COUNTY":return "county";case "RANK":return "rank_no";case "SHOP":return "shop_id,shop_name,county";case "SKU":return "shop_id,shop_name,sku_id,sku_name,category";case "AGENT":return "shop_id,shop_name,agent_id,agent_name,rank_no";case "CUSTOMER":return "shop_id,shop_name,buyer_id,buyer_name";case "DAY":return "business_day";case "MONTH":return "substring(business_day,1,7)";case "ORDER":return "order_id,shop_id,shop_name,buyer_id,buyer_name,order_type,order_status";default:throw new BusinessException("报表维度无效");}}
 private String aggregate(){return "count(distinct case when paid>refunded_paid then order_id else null end) orders,coalesce(sum(qty-refunded_qty),0) quantity,coalesce(sum(paid),0) gross_sales,coalesce(sum(refunded_paid),0) refunds,coalesce(sum(paid-refunded_paid),0) net_sales,coalesce(sum(net_cost),0) distribution_cost,coalesce(sum(case when cost_known=true then paid-refunded_paid else 0 end),0) known_cost_sales,coalesce(sum(case when cost_known=false then paid-refunded_paid else 0 end),0) unknown_cost_sales,coalesce(sum(earnings),0) earnings,count(distinct case when order_status='COMPLETED' and paid>refunded_paid then buyer_id else null end) completed_customers";}
 public List<Map<String,Object>> rows(Actor a,String id,String dimension,int page,int size){Map<String,Object>j=checked(a,id);require("COMPLETED".equals(str(j,"status")),"报表尚未完成");require(page>0&&size>0&&size<=1000,"报表分页无效");String g=group(dimension),select="DAY".equals(dimension)?"business_day as `day`":"MONTH".equals(dimension)?"substring(business_day,1,7) as `day`":g;List<Map<String,Object>>rows=db.jdbc().queryForList("select "+select+","+aggregate()+" from hx_report_line where job_id=? and matched=true group by "+g+" order by "+(Arrays.asList("DAY","MONTH").contains(dimension)?g:"net_sales desc,"+g)+" limit ? offset ?",id,size,Math.multiplyExact(page-1,size));Map<String,Object>f=db.parse(j.get("filters_json"));long days=ChronoUnit.DAYS.between(LocalDate.parse(str(f,"from")),LocalDate.parse(str(f,"to")))+1;for(Map<String,Object>r:rows){r.put("distributionMargin",number(r,"known_cost_sales")-number(r,"distribution_cost"));if("SKU".equals(dimension)){Map<String,Object>stock=db.optional("select available,locked,defective,warning_qty,in_transit,average_stock from hx_report_stock where job_id=? and shop_id=? and sku_id=?",id,r.get("shop_id"),r.get("sku_id"));if(stock!=null){r.putAll(stock);r.put("turnoverDays",number(r,"quantity")>0?new BigDecimal(String.valueOf(stock.get("average_stock"))).multiply(BigDecimal.valueOf(days)).divide(BigDecimal.valueOf(number(r,"quantity")),2,RoundingMode.HALF_UP):null);}}}return rows;}
 public Map<String,Object> view(Actor a,String id,String dimension,int page,int size){Map<String,Object>j=checked(a,id);Map<String,Object>f=db.parse(j.get("filters_json"));j.remove("filters_json");j.put("filters",f);j.put("progress",number(j,"total_rows")==0?("COMPLETED".equals(str(j,"status"))?100:0):number(j,"processed_rows")*100/number(j,"total_rows"));if("COMPLETED".equals(str(j,"status"))){Map<String,Object>sum=db.one("select "+aggregate()+" from hx_report_line where job_id=? and matched=true",id);long repeat=db.jdbc().queryForObject("select count(*) from (select buyer_id from hx_report_line where job_id=? and matched=true and order_status='COMPLETED' and paid>refunded_paid group by buyer_id having count(distinct order_id)>=2) r",Long.class,id);sum.put("repeatCustomers",repeat);sum.put("repeatBps",number(sum,"completed_customers")==0?0:SettlementCalculator.proportion(repeat,10000,number(sum,"completed_customers")));sum.put("distributionMargin",number(sum,"known_cost_sales")-number(sum,"distribution_cost"));j.put("summary",sum);j.put("rows",rows(a,id,dimension,page,size));j.put("totalGroups",db.jdbc().queryForObject("select count(*) from (select "+group(dimension)+" from hx_report_line where job_id=? and matched=true group by "+group(dimension)+") g",Long.class,id));String grain=ChronoUnit.DAYS.between(LocalDate.parse(str(f,"from")),LocalDate.parse(str(f,"to")))>60?"MONTH":"DAY";j.put("trendGrain",grain);j.put("trend",rows(a,id,grain,1,1000));j.put("inventory",inventory(a,id,1,100));j.put("inventoryTotal",db.jdbc().queryForObject("select count(*) from hx_report_stock where job_id=?",Long.class,id));j.put("inventoryScope","库存为所选商城及商品全量快照；代理和客户筛选仅影响销量，周转天数不适用于个人业绩判断");}return j;}
 public List<Map<String,Object>> inventory(Actor a,String id,int page,int size){Map<String,Object>j=checked(a,id);require("COMPLETED".equals(str(j,"status")),"报表尚未完成");require(page>0&&size>0&&size<=1000,"报表分页无效");Map<String,Object>f=db.parse(j.get("filters_json"));long days=ChronoUnit.DAYS.between(LocalDate.parse(str(f,"from")),LocalDate.parse(str(f,"to")))+1;List<Map<String,Object>>rows=db.jdbc().queryForList("select s.*,(select coalesce(sum(l.qty-l.refunded_qty),0) from hx_report_line l where l.job_id=s.job_id and l.shop_id=s.shop_id and l.sku_id=s.sku_id and l.matched=true) quantity from hx_report_stock s where s.job_id=? order by s.available,s.shop_id,s.sku_id limit ? offset ?",id,size,Math.multiplyExact(page-1,size));for(Map<String,Object>r:rows){r.remove("job_id");r.put("stockStatus",number(r,"available")==0?"缺货":number(r,"available")<=number(r,"warning_qty")?"库存预警":number(r,"quantity")==0?"本期无销量":"正常");r.put("turnoverDays",number(r,"quantity")>0?new BigDecimal(String.valueOf(r.get("average_stock"))).multiply(BigDecimal.valueOf(days)).divide(BigDecimal.valueOf(number(r,"quantity")),2,RoundingMode.HALF_UP):null);}return rows;}
 public Map<String,Object> exportAudit(Actor a,String id,String dimension){Map<String,Object>j=checked(a,id);require("COMPLETED".equals(str(j,"status")),"报表尚未完成");if(!"INVENTORY".equals(dimension))group(dimension);db.audit(a,number(j,"shop_id"),"REPORT_EXPORT",id,null,map("dimension",dimension,"snapshotAt",j.get("snapshot_at"),"filters",db.parse(j.get("filters_json"))));return j;}
}
